package com.creditsense.repo;
import com.creditsense.domain.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public final class Repositories { private Repositories(){} public interface Users extends JpaRepository<User,UUID>{Optional<User> findByEmail(String email);} public interface Applicants extends JpaRepository<Applicant,UUID>{Optional<Applicant> findByUserId(UUID id); Optional<Applicant> findFirstByPan(String pan);} public interface Applications extends JpaRepository<LoanApplication,UUID>{List<LoanApplication> findByApplicantUserId(UUID id); long countByApplicantIdAndSubmittedAtAfter(UUID id,java.time.Instant when);} public interface Checks extends JpaRepository<ComplianceCheck,UUID>{List<ComplianceCheck> findByApplicationId(UUID id); void deleteByApplicationId(UUID id);} public interface Assessments extends JpaRepository<RiskAssessment,UUID>{Optional<RiskAssessment> findByApplicationId(UUID id);} public interface Audits extends JpaRepository<AuditLog,UUID>{} }
